using System;using UnityEngine;namespace LWS.TruckMinefield.Editor {
public static class MinefieldFixtures {public static void Run(){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Minefield fixture: "+label);count++;};check(MinefieldRules.Precision(123.44f)==1234&&MinefieldRules.Precision(123.46f)==1235,"display precision");check(MinefieldRules.Leaders(new[]{1234,1234,-1},7)==3,"tied heat leaders");check(MinefieldRules.Leaders(new[]{-1,-1},3)==0,"no fabricated incomplete score");check(MinefieldRules.MatchLeader(new[]{5,5,2},7,3,false,out int eligible,out bool tie)==-1&&eligible==3&&tie,"multiple match leaders require tiebreak");check(MinefieldRules.MatchLeader(new[]{5,6,2},3,2,true,out eligible,out tie)==1,"single next-heat leader resolves prior five-point tie");check(MinefieldRules.MatchLeader(new[]{6,6,2},3,3,true,out eligible,out tie)==-1&&eligible==3,"repeated tied tiebreak continues");check(MinefieldRules.DrivenFinish(MineAttempt.Driving,1600,1611,out float t)&&t>0&&t<1,"swept driven finish");check(!MinefieldRules.DrivenFinish(MineAttempt.Launched,1600,1611,out _),"airborne crossing cannot win");check(!MinefieldRules.DrivenFinish(MineAttempt.Driving,1611,1600,out _),"reverse crossing rejected");Debug.Log("MINEFIELD_RULE_FIXTURES_PASS count="+count);}}
}
